param(
  [string]$OutDir = (Join-Path $env:TEMP "lightnovel-reader-smoke-epubs")
)

$ErrorActionPreference = "Stop"
$repo = Resolve-Path (Join-Path $PSScriptRoot "..")
$appVersion = (Get-Content -Raw -Encoding UTF8 (Join-Path $repo "package.json") | ConvertFrom-Json).version

function Write-Utf8File($Path, $Content) {
  $dir = Split-Path -Parent $Path
  New-Item -ItemType Directory -Force $dir | Out-Null
  [System.IO.File]::WriteAllText($Path, $Content, [System.Text.UTF8Encoding]::new($false))
}

function New-SmokeEpub($BuildDir, $Target, $BookId, $Title, $SeriesIndex, $BodyText) {
  Remove-Item -LiteralPath $BuildDir -Recurse -Force -ErrorAction SilentlyContinue
  New-Item -ItemType Directory -Force (Join-Path $BuildDir "META-INF") | Out-Null
  New-Item -ItemType Directory -Force (Join-Path $BuildDir "OEBPS\Text") | Out-Null
  New-Item -ItemType Directory -Force (Join-Path $BuildDir "OEBPS\Images") | Out-Null

  Write-Utf8File (Join-Path $BuildDir "META-INF\container.xml") @"
<?xml version="1.0" encoding="UTF-8"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
  <rootfiles>
    <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>
  </rootfiles>
</container>
"@

  Write-Utf8File (Join-Path $BuildDir "OEBPS\content.opf") @"
<?xml version="1.0" encoding="UTF-8"?>
<package xmlns="http://www.idpf.org/2007/opf" version="3.0" unique-identifier="bookid">
  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
    <dc:identifier id="bookid">$BookId</dc:identifier>
    <dc:title>$Title</dc:title>
    <dc:creator>Smoke Tester</dc:creator>
    <dc:language>zh-CN</dc:language>
    <dc:description>Temporary EPUB generated for lightnovel-reader v$appVersion desktop smoke testing.</dc:description>
    <meta property="belongs-to-collection" id="series">Smoke Test Series</meta>
    <meta refines="#series" property="group-position">$SeriesIndex</meta>
  </metadata>
  <manifest>
    <item id="cover" href="Images/cover.png" media-type="image/png" properties="cover-image"/>
    <item id="chap1" href="Text/chapter1.xhtml" media-type="application/xhtml+xml"/>
  </manifest>
  <spine>
    <itemref idref="chap1"/>
  </spine>
</package>
"@

  Write-Utf8File (Join-Path $BuildDir "OEBPS\Text\chapter1.xhtml") @"
<!doctype html>
<html xmlns="http://www.w3.org/1999/xhtml">
  <head><title>Chapter 1</title></head>
  <body>
    <h1>$Title</h1>
    <p>$BodyText</p>
    <figure>
      <img src="../Images/cover.png" alt="Smoke inline illustration"/>
      <figcaption>Inline illustration used to verify reader-img resource loading after sanitization.</figcaption>
    </figure>
    <p>Select part of this sentence, create a highlight, close the app, then reopen it to verify annotation restore.</p>
    <p>This extra paragraph is here to make page turning and progress persistence easier to test.</p>
  </body>
</html>
"@

  $png = [Convert]::FromBase64String("")
  [System.IO.File]::WriteAllBytes((Join-Path $BuildDir "OEBPS\Images\cover.png"), $png)

  New-Item -ItemType Directory -Force (Split-Path -Parent $Target) | Out-Null
  Remove-Item -LiteralPath $Target -Force -ErrorAction SilentlyContinue
  $tmpZip = Join-Path (Split-Path -Parent $Target) "tmp-$BookId.zip"
  Remove-Item -LiteralPath $tmpZip -Force -ErrorAction SilentlyContinue
  [System.IO.Compression.ZipFile]::CreateFromDirectory($BuildDir, $tmpZip)
  Move-Item -LiteralPath $tmpZip -Destination $Target
}

Add-Type -AssemblyName System.IO.Compression.FileSystem

Remove-Item -LiteralPath $OutDir -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force $OutDir | Out-Null

$build = Join-Path $OutDir "_build"
$one = Join-Path $OutDir "one\smoke-test-lightnovel-vol1.epub"
$folderCopy = Join-Path $OutDir "folder\Smoke Test Series\Vol01\smoke-test-lightnovel-vol1-copy.epub"
$folderVol2 = Join-Path $OutDir "folder\Smoke Test Series\Vol02\smoke-test-lightnovel-vol2.epub"

New-SmokeEpub $build $one "smoke-lightnovel-vol1" "Smoke Test Light Novel Vol.1" "1" "Volume one is used for open-book, progress, cover, and duplicate-import smoke testing."
New-Item -ItemType Directory -Force (Split-Path -Parent $folderCopy) | Out-Null
Copy-Item -LiteralPath $one -Destination $folderCopy
New-SmokeEpub $build $folderVol2 "smoke-lightnovel-vol2" "Smoke Test Light Novel Vol.2" "2" "Volume two is used for folder import and series metadata smoke testing."

Remove-Item -LiteralPath $build -Recurse -Force -ErrorAction SilentlyContinue

Write-Host "Smoke EPUBs generated:"
Get-ChildItem -LiteralPath $OutDir -Recurse -Filter *.epub |
  Sort-Object FullName |
  ForEach-Object { Write-Host ("- " + $_.FullName) }
